"use client";
import { useId, useMemo, useState } from "react";
import { Badge } from "@ui/badge";
import { Button } from "@ui/button";
import { Container, ContainerBody, ContainerFooter, ContainerHeader } from "@ui/container";
import { InlineNotice } from "@ui/inline-notice";
import { LiveLine, LiveLineChart } from "@ui/live-line-chart";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@ui/select";
import { TabItem, TabPanel, Tabs, TabsList } from "@ui/tabs";
import { Tooltip } from "@ui/tooltip";
import { createIconSlot } from "@lib/icon-context";
import { cn } from "@lib/utils";
import { fleetHealthLabels, fleetMetricColor, fleetMetricValue } from "./fleet-health-data";
import { FleetHealthMatrix } from "./fleet-health-matrix";
import type { FleetHealthMetric, FleetHealthProps } from "./fleet-health-types";
const Info = createIconSlot("doc-info-item");
const Server = createIconSlot("monitor");
const Settings = createIconSlot("settings");
/** Domain visualization: segmented telemetry, not a control or a capacity claim when unknown. */
function TelemetryTicks({ value, total, label }: {
    value: number | null;
    total: number | null;
    label: string;
}) {
    const known = value !== null && total !== null && Number.isFinite(value) && Number.isFinite(total) && value >= 0 && total > 0;
    const ratio = known ? Math.min(1, value / total) : 0;
    return <div role="img" aria-label={label} className="mt-2 flex h-3 w-full gap-0.5" data-slot="fleet-telemetry-ticks" data-known={known}>
    {Array.from({ length: 26 }, (_, index) => <span key={index} aria-hidden className={cn("h-full min-w-0 flex-1 rounded-full", known && index / 26 < ratio ? "bg-brand" : "bg-border-subtle")}/>)}
  </div>;
}
export function FleetHealth({ data, clusterId, clusters, onClusterChange, metric: controlledMetric, onMetricChange, selectedNodeId: controlledNode, onNodeSelect, temperatureThreshold = 84, live = false, refreshIntervalMs = 1600, region, onRebalance, rebalancing = false, onSettings, footerActions, notice, labels: overrides, locale = "en-US", className }: FleetHealthProps) {
    const titleId = useId();
    const labels = { ...fleetHealthLabels, ...overrides };
    const [localMetric, setLocalMetric] = useState<FleetHealthMetric>("utilization");
    const [localNode, setLocalNode] = useState<string | null>(null);
    const metric = controlledMetric ?? localMetric;
    const selected = controlledNode === undefined ? localNode : controlledNode;
    const selectedNode = data.nodes.some((node) => node.id === selected) ? selected : null;
    const threshold = Number.isFinite(temperatureThreshold) ? temperatureThreshold : 84;
    const numberFormats = useMemo(() => [
        new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }),
        new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }),
    ], [locale]);
    const format = (value: number | null, digits: 0 | 1 = 0) => value !== null && Number.isFinite(value) && value >= 0
        ? numberFormats[digits].format(value) : "—";
    const gpus = data.nodes.flatMap((node) => node.gpus);
    let hot = 0;
    let draining = 0;
    let observedTemperatures = 0;
    let unknownTemperature = false;
    for (const gpu of gpus) {
        if (gpu.status === "draining")
            draining++;
        if (gpu.status === "offline")
            continue;
        const temperature = fleetMetricValue(gpu, "temperature");
        if (temperature === null)
            unknownTemperature = true;
        else {
            observedTemperatures++;
            if (temperature >= threshold)
                hot++;
        }
    }
    const temperatureStatus = hot ? `${format(hot)} ${labels.hot}`
        : unknownTemperature || observedTemperatures === 0 ? labels.unknown : labels.healthy;
    const change = data.changePercent !== null && Number.isFinite(data.changePercent) ? data.changePercent : null;
    function selectNode(id: string | null) { setLocalNode(id); onNodeSelect?.(id); }
    const changeMetric = (value: string) => { const next = value as FleetHealthMetric; setLocalMetric(next); onMetricChange?.(next); };
    const metricLabel = metric === "temperature" ? labels.temperature : metric === "memory" ? labels.memory : labels.utilization;
    const matrix = <>
    {data.nodes.length === 0 ? <p role="status" className="py-12 text-center text-body text-fg-muted">{labels.empty}</p>
            : <FleetHealthMatrix nodes={data.nodes} metric={metric} selectedNodeId={selectedNode} onNodeSelect={selectNode} threshold={threshold} labels={labels} format={format}/>}
    <div className="mt-4 flex flex-wrap items-center justify-between gap-2 text-label text-fg-subtle">
      <span>{labels.hint}</span>
      <div className="flex items-center gap-2" aria-label={`${metricLabel}: ${metric === "temperature" ? "30–90°C" : "0–100%"}`}>
        <span>{metric === "temperature" ? "30°C" : "0%"}</span><span aria-hidden className="flex h-3 w-24 gap-0.5">{Array.from({ length: 26 }, (_, index) => <span key={index} className="h-full min-w-0 flex-1 rounded-full" style={{ backgroundColor: fleetMetricColor(metric === "temperature" ? 30 + index / 25 * 60 : index / 25 * 100, metric) }}/>)}</span><span>{metric === "temperature" ? "90°C" : "100%"}</span>
      </div>
    </div>
    {selectedNode && <div className="mt-2 flex justify-end"><Button size="sm" variant="ghost" onClick={() => selectNode(null)}>{labels.clearFocus}</Button></div>}
  </>;
    return <Container role="region" aria-labelledby={titleId} className={cn("w-full max-w-xl", className)}>
    <ContainerHeader>
      <div className="flex items-center gap-2"><h2 id={titleId} className="text-body font-medium text-fg-default">{labels.title}</h2>
        <Tooltip content={labels.info}><Button variant="ghost" size="sm" iconOnly aria-label={labels.info}><Info /></Button></Tooltip>
      </div>
      <div className="flex flex-wrap items-center gap-1">
        <Select size="sm" value={clusterId} onValueChange={onClusterChange} disabled={!onClusterChange}>
          <SelectTrigger icon={Server} aria-label={labels.cluster}/>
          <SelectContent>{clusters.map((cluster) => <SelectItem key={cluster.id} value={cluster.id}>{cluster.label}</SelectItem>)}</SelectContent>
        </Select>
        {onSettings && <Button variant="ghost" size="sm" iconOnly onClick={onSettings} aria-label={labels.settings}><Settings /></Button>}
      </div>
    </ContainerHeader>
    <ContainerBody>
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div className="min-w-0 flex-1 basis-64"><p className="font-mono text-label uppercase tracking-wide text-fg-subtle">{labels.tokens}</p>
          <div className="mt-2 flex flex-wrap items-center gap-3"><strong className="break-all text-display font-medium tabular-nums text-fg-default">{format(data.tokensPerSecond)}</strong>
            {change !== null && <Badge status={change < 0 ? "warning" : "success"} size="sm">{change >= 0 ? "↑" : "↓"} {format(Math.abs(change), 1)}%</Badge>}
          </div>
          <p className="mt-2 font-mono text-label uppercase text-fg-muted">{labels.comparison} · {labels.ttft} {format(data.ttftMs)} ms · {format(data.modelCount)} {labels.models}</p>
        </div>
        <div className="ml-auto w-40 shrink-0 pt-2">
          {data.throughput.length > 0 && data.tokensPerSecond !== null && Number.isFinite(data.tokensPerSecond) && data.tokensPerSecond >= 0
            ? <LiveLineChart data={data.throughput} value={data.tokensPerSecond} window={64} paused={!live} exaggerate margin={{ top: 8, right: 8, bottom: 8, left: 0 }} style={{ height: 64 }}><LiveLine dataKey="value" stroke="var(--brand)" dotSize={2.5} badge={false} pulse={live}/></LiveLineChart>
            : <div className="flex h-16 items-center justify-center text-label text-fg-subtle">—</div>}
          <p className="mt-1 text-right font-mono text-label uppercase text-fg-subtle">{labels.lastWindow}</p>
        </div>
      </div>
      <dl className="mt-4 grid grid-cols-3 gap-5 border-t-hairline border-dashed border-border-subtle pt-4">
        <div><dt className="font-mono text-label uppercase text-fg-subtle">{labels.utilization}</dt><dd className="mt-1 text-body font-medium tabular-nums text-fg-default">{format(data.utilization)} <span className="font-normal text-fg-subtle">%</span></dd><TelemetryTicks value={data.utilization} total={100} label={`${labels.utilization}: ${format(data.utilization)}%`}/></div>
        <div><dt className="font-mono text-label uppercase text-fg-subtle">{labels.queue}</dt><dd className="mt-1 text-body font-medium tabular-nums text-fg-default">{format(data.queueDepth)} <span className="font-normal text-fg-subtle">req</span></dd><TelemetryTicks value={data.queueDepth} total={data.queueCapacity} label={`${labels.queue}: ${format(data.queueDepth)} / ${format(data.queueCapacity)}`}/></div>
        <div><dt className="font-mono text-label uppercase text-fg-subtle">{labels.power}</dt><dd className="mt-1 text-body font-medium tabular-nums text-fg-default">{format(data.powerKw, 1)} <span className="font-normal text-fg-subtle">/ {format(data.powerCapacityKw)} kW</span></dd><TelemetryTicks value={data.powerKw} total={data.powerCapacityKw} label={`${labels.power}: ${format(data.powerKw, 1)} / ${format(data.powerCapacityKw)} kW`}/></div>
      </dl>
    </ContainerBody>
    <ContainerBody>
      <Tabs value={metric} onValueChange={changeMetric} variant="segment" color="default">
        <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
          <div><h3 className="text-body font-medium text-fg-default">{labels.gpus} · {format(gpus.length)}</h3>
            <p className="mt-1 font-mono text-label uppercase text-fg-subtle">{format(data.nodes.length)} {labels.nodes} · {temperatureStatus}{draining > 0 ? ` · ${format(draining)} ${labels.draining}` : ""}</p>
          </div>
          <TabsList aria-label={labels.matrix}><TabItem value="utilization" label={labels.utilization}/><TabItem value="memory" label={labels.memory}/><TabItem value="temperature" label={labels.temperature}/></TabsList>
        </div>
        <TabPanel value={metric}>{matrix}</TabPanel>
      </Tabs>
    </ContainerBody>
    {notice && <div className="px-3"><InlineNotice role="status">{notice}</InlineNotice></div>}
    <ContainerFooter>
      <div className="mr-auto flex min-w-0 flex-wrap items-center gap-2">{footerActions}<Badge variant="plain" status={live ? "success" : "neutral"} size="sm">{live ? labels.live : labels.paused}</Badge>
        <span className="font-mono text-label uppercase text-fg-subtle">· {labels.every} {format(refreshIntervalMs / 1000, 1)} s{region ? ` · ${region}` : ""}</span>
      </div>
      {onRebalance && <Button onClick={onRebalance} loading={rebalancing} disabled={gpus.length === 0} size="sm">{rebalancing ? labels.rebalancing : labels.rebalance}</Button>}
    </ContainerFooter>
  </Container>;
}

import type { ReactNode } from "react";
import type { LiveLinePoint } from "@ui/live-line-chart";
export type FleetHealthMetric = "utilization" | "memory" | "temperature";
export interface FleetGpu {
    id: string;
    /** Stable display index within its node, independent of array position. */
    index: number;
    status: "active" | "idle" | "draining" | "offline";
    utilization: number | null;
    memoryUsedGb: number | null;
    memoryTotalGb: number | null;
    temperatureC: number | null;
    powerW: number | null;
    job: string | null;
}
export interface FleetNode {
    id: string;
    name: string;
    model: string;
    gpus: readonly FleetGpu[];
}
export interface FleetHealthSnapshot {
    tokensPerSecond: number | null;
    changePercent: number | null;
    ttftMs: number | null;
    modelCount: number | null;
    utilization: number | null;
    queueDepth: number | null;
    queueCapacity: number | null;
    powerKw: number | null;
    powerCapacityKw: number | null;
    /** Unix seconds, ascending; the host owns sampling and the streaming connection. */
    throughput: LiveLinePoint[];
    nodes: readonly FleetNode[];
}
export interface FleetHealthLabels {
    title: string;
    info: string;
    cluster: string;
    tokens: string;
    comparison: string;
    ttft: string;
    models: string;
    lastWindow: string;
    utilization: string;
    queue: string;
    power: string;
    gpus: string;
    nodes: string;
    hot: string;
    healthy: string;
    draining: string;
    idle: string;
    offline: string;
    memory: string;
    temperature: string;
    job: string;
    noJob: string;
    hint: string;
    clearFocus: string;
    focusNode: string;
    live: string;
    paused: string;
    every: string;
    rebalance: string;
    rebalancing: string;
    settings: string;
    empty: string;
    unknown: string;
    matrix: string;
}
export interface FleetHealthProps {
    data: FleetHealthSnapshot;
    clusterId: string;
    clusters: readonly {
        id: string;
        label: string;
    }[];
    onClusterChange?: (id: string) => void;
    metric?: FleetHealthMetric;
    onMetricChange?: (metric: FleetHealthMetric) => void;
    selectedNodeId?: string | null;
    onNodeSelect?: (id: string | null) => void;
    /** Defaults to 84°C; hot status is independent of the selected color metric. */
    temperatureThreshold?: number;
    live?: boolean;
    refreshIntervalMs?: number;
    region?: string;
    onRebalance?: () => void;
    rebalancing?: boolean;
    onSettings?: () => void;
    footerActions?: ReactNode;
    notice?: ReactNode;
    labels?: Partial<FleetHealthLabels>;
    locale?: string;
    className?: string;
}

import type { FleetGpu, FleetHealthLabels, FleetHealthMetric } from "./fleet-health-types";
export const fleetHealthLabels: FleetHealthLabels = {
    title: "Fleet health", info: "Live inference throughput and GPU telemetry.", cluster: "Cluster",
    tokens: "Tokens served / s", comparison: "vs 1h ago", ttft: "TTFT P50", models: "models",
    lastWindow: "Last 64 s", utilization: "Fleet util", queue: "Queue depth", power: "Power",
    gpus: "GPUs", nodes: "nodes", hot: "running hot", healthy: "All within limits",
    draining: "draining", idle: "Idle", offline: "Offline", memory: "Memory", temperature: "Temp",
    job: "Job", noJob: "No job", hint: "Hover a GPU · click a node to focus", clearFocus: "Clear node focus",
    focusNode: "Focus node", live: "Live", paused: "Paused", every: "every", rebalance: "Rebalance",
    rebalancing: "Rebalancing", settings: "Fleet settings",
    empty: "No GPU nodes in this cluster", unknown: "Unknown", matrix: "GPU telemetry",
};
export const fleetHealthZhLabels: FleetHealthLabels = {
    title: "集群健康", info: "实时推理吞吐量与 GPU 遥测。", cluster: "集群",
    tokens: "每秒处理 Token", comparison: "相比 1 小时前", ttft: "首 Token 延迟 P50", models: "个模型",
    lastWindow: "最近 64 秒", utilization: "集群利用率", queue: "排队请求", power: "功耗",
    gpus: "GPU", nodes: "个节点", hot: "张过热", healthy: "均在阈值内",
    draining: "张排空中", idle: "空闲", offline: "离线", memory: "显存", temperature: "温度",
    job: "任务", noJob: "无任务", hint: "悬停查看 GPU · 点击节点聚焦", clearFocus: "取消节点聚焦",
    focusNode: "聚焦节点", live: "实时", paused: "已暂停", every: "每", rebalance: "重新均衡",
    rebalancing: "均衡中", settings: "集群设置",
    empty: "此集群暂无 GPU 节点", unknown: "未知", matrix: "GPU 遥测",
};
/** Unknown and invalid observations stay unknown, never turn into idle/zero. */
export function fleetMetricValue(gpu: FleetGpu, metric: FleetHealthMetric): number | null {
    const value = metric === "memory"
        ? gpu.memoryUsedGb !== null && gpu.memoryTotalGb !== null && gpu.memoryTotalGb > 0
            && Number.isFinite(gpu.memoryUsedGb) && Number.isFinite(gpu.memoryTotalGb)
            && gpu.memoryUsedGb >= 0 && gpu.memoryUsedGb <= gpu.memoryTotalGb
            ? gpu.memoryUsedGb / gpu.memoryTotalGb * 100 : null
        : metric === "temperature" ? gpu.temperatureC : gpu.utilization;
    return value !== null && Number.isFinite(value) && value >= 0
        && (metric === "temperature" || value <= 100) ? value : null;
}
export function fleetNodeAverage(gpus: readonly FleetGpu[], metric: FleetHealthMetric): number | null {
    // Offline hardware has no current observation; do not dilute live averages with zero.
    let total = 0;
    let count = 0;
    for (const gpu of gpus) {
        if (gpu.status === "offline")
            continue;
        const value = fleetMetricValue(gpu, metric);
        if (value === null)
            return null;
        total += value;
        count++;
    }
    return count ? total / count : null;
}
export function fleetMetricColor(value: number | null, metric: FleetHealthMetric): string {
    if (value === null)
        return "var(--surface-base)";
    const ratio = Math.max(0, Math.min(1, metric === "temperature" ? (value - 30) / 60 : value / 100));
    return `color-mix(in oklab, var(--brand) ${Math.round(12 + ratio * 88)}%, var(--surface-floating))`;
}

"use client";
import { useRef, useState, type KeyboardEvent } from "react";
import { Tooltip, TooltipProvider } from "@ui/tooltip";
import { cn } from "@lib/utils";
import { fleetMetricColor, fleetMetricValue, fleetNodeAverage } from "./fleet-health-data";
import type { FleetGpu, FleetHealthLabels, FleetHealthMetric, FleetNode } from "./fleet-health-types";
export function FleetHealthMatrix({ nodes, metric, selectedNodeId, onNodeSelect, threshold, labels, format }: {
    nodes: readonly FleetNode[];
    metric: FleetHealthMetric;
    selectedNodeId: string | null;
    onNodeSelect: (id: string | null) => void;
    threshold: number;
    labels: FleetHealthLabels;
    format: (value: number | null, digits?: 0 | 1) => string;
}) {
    const root = useRef<HTMLDivElement>(null);
    const [focusedId, setFocusedId] = useState<string | null>(null);
    const allIds = nodes.flatMap((node) => node.gpus.map((gpu) => JSON.stringify([node.id, gpu.id])));
    const gpuColumns = nodes.reduce((max, node) => Math.max(max, node.gpus.length), 0);
    const tabStop = focusedId && allIds.includes(focusedId) ? focusedId : allIds[0];
    const valueText = (value: number | null) => `${format(value)}${value === null ? "" : metric === "temperature" ? "°C" : "%"}`;
    function inspect(event: KeyboardEvent<HTMLButtonElement>, row: number, col: number) {
        let nextRow = row;
        let nextCol = col;
        switch (event.key) {
            case "ArrowRight":
                nextCol++;
                break;
            case "ArrowLeft":
                nextCol--;
                break;
            case "ArrowDown":
            case "ArrowUp": {
                const direction = event.key === "ArrowDown" ? 1 : -1;
                for (let candidate = row + direction; candidate >= 0 && candidate < nodes.length; candidate += direction) {
                    if (nodes[candidate].gpus.length) {
                        nextRow = candidate;
                        break;
                    }
                }
                break;
            }
            case "Home":
                nextCol = 0;
                if (event.ctrlKey || event.metaKey)
                    nextRow = nodes.findIndex((node) => node.gpus.length > 0);
                break;
            case "End":
                if (event.ctrlKey || event.metaKey)
                    nextRow = nodes.findLastIndex((node) => node.gpus.length > 0);
                nextCol = nodes[nextRow].gpus.length - 1;
                break;
            case "Escape":
                onNodeSelect(null);
                return;
            default: return;
        }
        event.preventDefault();
        nextRow = Math.max(0, Math.min(nodes.length - 1, nextRow));
        nextCol = Math.max(0, Math.min(nodes[nextRow].gpus.length - 1, nextCol));
        const gpu = nodes[nextRow].gpus[nextCol];
        if (!gpu)
            return;
        const id = JSON.stringify([nodes[nextRow].id, gpu.id]);
        const target = Array.from(root.current?.querySelectorAll<HTMLButtonElement>("[data-gpu]") ?? []).find((button) => button.dataset.gpu === id);
        setFocusedId(id);
        target?.focus();
    }
    function details(node: FleetNode, gpu: FleetGpu) {
        const rows = [
            [labels.utilization, `${format(fleetMetricValue(gpu, "utilization"))}%`],
            [labels.memory, `${format(gpu.memoryUsedGb, 1)} / ${format(gpu.memoryTotalGb)} GB`],
            [labels.temperature, `${format(gpu.temperatureC)}°C`],
            [labels.power, `${format(gpu.powerW)} W`], [labels.job, gpu.job ?? labels.noJob],
        ];
        return <div className="min-w-48 space-y-2 text-label">
      <div className="flex items-center justify-between gap-4"><span className="font-medium">{node.name} · GPU {gpu.index}</span><span className="opacity-70">{node.model}</span></div>
      <dl className="space-y-1">{rows.map(([label, value]) => <div key={label} className="flex justify-between gap-4"><dt className="opacity-70">{label}</dt><dd className="max-w-48 break-words text-right tabular-nums">{value}</dd></div>)}</dl>
      {gpu.status !== "active" && <p className="border-t-hairline border-current pt-1 opacity-70">{gpu.status === "draining" ? labels.draining : gpu.status === "offline" ? labels.offline : labels.idle}</p>}
    </div>;
    }
    return <TooltipProvider delayDuration={120}><div ref={root} className="min-w-0 overflow-x-auto py-1">
    <table aria-label={labels.matrix} className="w-full min-w-80 border-separate border-spacing-x-1 border-spacing-y-1 text-label">
      <tbody>{nodes.map((node, row) => {
            const dimmed = selectedNodeId !== null && selectedNodeId !== node.id;
            return <tr key={node.id} data-node={node.id} className={cn("transition-opacity duration-fast motion-reduce:transition-none", dimmed && "opacity-35")}>
          <th scope="row" className="w-24 pr-2 text-left font-normal"><button type="button" aria-pressed={selectedNodeId === node.id} aria-label={`${labels.focusNode} ${node.name}`} onClick={() => onNodeSelect(selectedNodeId === node.id ? null : node.id)} className="flex w-full items-center gap-2 rounded-sm text-fg-muted outline-none hover:text-fg-default focus-visible:ring-2 focus-visible:ring-focus-ring">
            <span className="whitespace-nowrap font-mono">{node.name}</span><span className="text-label text-fg-subtle">{node.model}</span>
          </button></th>
          {node.gpus.map((gpu, col) => {
                    const id = JSON.stringify([node.id, gpu.id]);
                    const value = gpu.status === "offline" ? null : fleetMetricValue(gpu, metric);
                    const temperature = fleetMetricValue(gpu, "temperature");
                    const hot = gpu.status !== "offline" && temperature !== null && temperature >= threshold;
                    return <td key={gpu.id}><Tooltip content={details(node, gpu)}><button type="button" data-gpu={id} aria-label={`${node.name} · GPU ${gpu.index} · ${metric === "temperature" ? labels.temperature : metric === "memory" ? labels.memory : labels.utilization}: ${valueText(value)}${hot ? ` · ${labels.hot}` : ""}${gpu.status !== "active" ? ` · ${gpu.status === "draining" ? labels.draining : gpu.status === "idle" ? labels.idle : labels.offline}` : ""}`} tabIndex={id === tabStop ? 0 : -1} onFocus={() => setFocusedId(id)} onKeyDown={(event) => inspect(event, row, col)} aria-pressed={selectedNodeId === node.id} onClick={() => onNodeSelect(selectedNodeId === node.id ? null : node.id)} className="relative block h-6 w-full min-w-5 rounded-sm border-hairline border-border-subtle outline-none transition-colors duration-fast hover:ring-2 hover:ring-focus-ring focus-visible:ring-2 focus-visible:ring-focus-ring motion-reduce:transition-none" style={{ backgroundColor: fleetMetricColor(value, metric),
                            backgroundImage: gpu.status === "draining" ? "repeating-linear-gradient(135deg, transparent, transparent 2px, var(--surface-floating) 2px, var(--surface-floating) 4px)" : undefined }}>
              {hot && <span aria-hidden className="absolute right-0.5 top-0.5 size-1.5 rounded-full bg-fg-danger ring-1 ring-surface-floating"/>}
              {value === null && <span aria-hidden className="block text-label text-fg-muted">—</span>}
            </button></Tooltip></td>;
                })}
          {node.gpus.length < gpuColumns && <td colSpan={gpuColumns - node.gpus.length}/>}
          <td className="w-12 pl-2 text-right font-mono text-fg-subtle">{valueText(fleetNodeAverage(node.gpus, metric))}</td>
        </tr>;
        })}</tbody>
    </table>
  </div></TooltipProvider>;
}

import type { FleetHealthSnapshot } from "./fleet-health-types";
export const fleetHealthDemoClusters = [
    { id: "kestrel-iad-3", label: "kestrel-iad-3" },
    { id: "kestrel-sfo-1", label: "kestrel-sfo-1" },
];
/** Deterministic, local fixture. Call with the host's current time to stream it. */
export function createFleetHealthDemoData(step = 0, nowSeconds = 0, clusterId = "kestrel-iad-3"): FleetHealthSnapshot {
    const remote = clusterId === "kestrel-sfo-1";
    const bases = remote ? [62, 70, 58, 46] : [81, 76, 89, 54, 70, 83, 79, 53];
    const nodes = bases.map((base, row) => ({
        id: `${clusterId}-node-${row}`, name: `ks-${row < 5 ? "a" : "b"}${String(row < 5 ? row + 1 : row - 4).padStart(2, "0")}`,
        model: row < 5 ? "H100" : "B200",
        gpus: Array.from({ length: 8 }, (_, col) => {
            const status = row === 3 && col === 6 ? "draining" as const
                : (row === 3 || row === 7) && col === 7 ? "idle" as const : "active" as const;
            const utilization = status === "idle" ? 0 : Math.max(0, Math.min(100, base + Math.round(Math.sin(step * 0.6 + col * 1.4 + row) * 4)));
            return { id: `gpu-${col}`, index: col + 1, status, utilization,
                memoryUsedGb: status === "idle" ? 0 : Math.round((base / 2 + col * 0.5) * 10) / 10,
                memoryTotalGb: row < 5 ? 80 : 180,
                temperatureC: status === "idle" ? 34 : row === 2 && col === 7 ? 86 : Math.round(39 + base * 0.44 + Math.sin(step + col) * 3),
                powerW: status === "idle" ? 45 : Math.round(140 + utilization * 5.2),
                job: status === "idle" ? null : row % 2 ? "quill-embed-v2" : "lumen-8b-chat" };
        }),
    }));
    const tokensPerSecond = Math.round((remote ? 960000 : 1890000) + Math.sin(step * 0.7) * 22000);
    return {
        tokensPerSecond, changePercent: 4.1 + Math.sin(step * 0.7) * 1.2,
        ttftMs: 216 + step % 5, modelCount: remote ? 3 : 5,
        utilization: remote ? 59 : 72 + step % 2, queueDepth: 88 + step % 7, queueCapacity: 400,
        powerKw: remote ? 18.4 : 38.2 + Math.sin(step) * 0.2, powerCapacityKw: remote ? 26 : 52,
        throughput: Array.from({ length: 41 }, (_, index) => ({ time: nowSeconds - (40 - index) * 1.6,
            value: index === 40 ? tokensPerSecond : Math.round((remote ? 960000 : 1890000) + Math.sin((index + step) * 0.38) * 23000 + Math.sin(index * 1.7) * 8000) })),
        nodes,
    };
}

